      const int end = index.ringOff[static_cast<std::size_t>(atom) + 1];
      auto &row = index.ringsContainingAtom[static_cast<std::size_t>(atom)];
      row.assign(index.ringCol.begin() + begin, index.ringCol.begin() + end);
