double minImage2(double dx, double dy, double dz, double lx, double ly,
                 double lz) {
  dx -= lx * std::floor(dx / lx + 0.5);
  dy -= ly * std::floor(dy / ly + 0.5);
  dz -= lz * std::floor(dz / lz + 0.5);
  return dx * dx + dy * dy + dz * dz;
}

void sortRow(int *a, int n) {
  for (int i = 1; i < n; ++i) {
    const int v = a[i];
    int j = i;
    while (j > 0 && a[j - 1] > v) {
      a[j] = a[j - 1];
      --j;
    }
    a[j] = v;
  }
}

