void countSourceShell2(const std::size_t *rowFirst, const int *cols, int nVertices, int src,
                       int maxDepth, int maxLvl, int minSize, int cap, std::vector<int> *hist,
                       int epoch) {
  shell2_detail::RowView graph{rowFirst, cols, nVertices};
  shell2_detail::DistOracle oracle;
  oracle.adj = &graph;
  oracle.hop2 = true;
  shell2_detail::gChordEpoch.store(epoch, std::memory_order_relaxed);
  thread_local shell2_detail::RingScratch scr;
  shell2_detail::countOne(graph, oracle, scr, src, nVertices, maxDepth, maxLvl, minSize, cap, hist);
}
